+/* ============================================================================
+   2. PET OVERLAY (transparent window: pet sprite + bubble)
+============================================================================ */
+html, body.overlay {
+  background: transparent !important;
+  overflow: hidden;
+  width: 100%;
+  height: 100%;
+  font-family: var(--font-ui);
+  cursor: default;
+}
+body.overlay, body.overlay * {
+  user-select: none;
+  -webkit-user-select: none;
+}
+
+#pet-root {
+  position: absolute;
+  bottom: 0;
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 5px;
+}
+#pet {
+  image-rendering: pixelated;
+  cursor: grab;
+}
+
+/* speech bubble: ember glass */
+.bubble {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  gap: 3px;
+  max-width: 270px;
+  padding: 9px 15px;
+  border-radius: 16px;
+  background: var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  color: var(--bubble-fg, #F6F0E4);
+  border: 1px solid var(--bubble-border, rgba(232, 176, 106, 0.22));
+  font-size: var(--bubble-font-size, 12px);
+  font-family: var(--bubble-font-family, var(--font-ui));
+  font-weight: 500;
+  line-height: 1.45;
+  text-align: center;
+  margin-bottom: 6px;
+  box-shadow:
+    0 10px 30px rgba(0, 0, 0, 0.45),
+    0 2px 8px rgba(0, 0, 0, 0.28),
+    inset 0 1px 0 rgba(255, 255, 255, 0.06);
+  transition: opacity 0.2s ease, transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
+}
+.bubble[hidden] { display: none; }
+.bubble::after {
+  content: "";
+  position: absolute;
+  left: 50%;
+  bottom: -6px;
+  transform: translateX(-50%);
+  border: 7px solid transparent;
+  border-top: 7px solid var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  border-bottom: 0;
+}
+.bubble .brow.focusable { cursor: pointer; border-radius: 8px; transition: background 0.12s; }
+.bubble .brow.focusable:hover { background: rgba(255, 255, 255, 0.10); }
+.bubble .approval { display: inline-flex; gap: 5px; margin-left: 6px; }
+.bubble .approval button {
+  font: inherit; font-size: 10px; font-weight: 600;
+  border: none; border-radius: 999px; padding: 1px 9px; cursor: pointer;
+}
+.bubble .approval .ap-allow { background: rgba(143, 216, 168, 0.16); color: var(--green); }
+.bubble .approval .ap-deny { background: rgba(229, 122, 110, 0.18); color: var(--red); }
+.bubble .brow {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line {
+  transition: opacity 0.18s ease;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line.fade { opacity: 0; }
+.bubble.capsule { border-radius: 999px; }
+
+.bubble .aicon { width: 14px; height: 14px; flex: 0 0 auto; object-fit: contain; }
+.bubble .rtitle { font-weight: 600; opacity: 0.88; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rproject { font-weight: 500; opacity: 0.82; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rsep { opacity: 0.35; }
+.bubble .amsg { font-weight: 500; opacity: 0.85; overflow: hidden; text-overflow: ellipsis; flex-shrink: 1; }
+.bubble .rstate { font-size: 0.85em; opacity: 0.55; }
+.bubble .clock { font-size: 0.85em; opacity: 0.45; font-variant-numeric: tabular-nums; }
+.bubble .xn {
+  font-size: 0.85em; font-weight: 600; opacity: 0.65;
+  padding: 0 6px; border-radius: 999px; background: rgba(255,255,255,0.10);
+}
+
+.bubble .brow.waiting .amsg {
+  color: var(--orange); font-weight: 600;
+  animation: waitflash 1.7s ease-in-out infinite;
+}
+@keyframes waitflash { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
+
+.bubble .amsg.shimmer {
+  background: linear-gradient(100deg,
+    var(--bubble-fg, #F6F0E4) 40%, rgba(255,255,255,0.45) 50%, var(--bubble-fg, #F6F0E4) 60%);
+  background-size: 220% 100%;
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  animation: shimmer 2.5s linear infinite;
+}
+@keyframes shimmer { from { background-position: 120% 0; } to { background-position: -120% 0; } }
+
+.bubble .sdot {
+  position: relative; width: 8px; height: 8px; border-radius: 50%;
+  flex: 0 0 auto; background: #8A8578;
+}
+.bubble .brow[data-state="working"] .sdot,
+.bubble .brow[data-state="registered"] .sdot { background: var(--amber); }
+.bubble .brow[data-state="waiting"] .sdot { background: var(--orange); }
+.bubble .brow[data-state="done"] .sdot { background: var(--green); }
+.bubble .sdot.plain.spin::after {
+  content: ""; position: absolute; inset: 0; border-radius: 50%;
+  background: inherit;
+  animation: bloom 1.5s ease-out infinite;
+}
+@keyframes bloom { 0% { transform: scale(1); opacity: 0.55; } 100% { transform: scale(2.4); opacity: 0; } }
+
+.bubble .sdot.claude { width: 14px; height: 14px; border-radius: 0; background: transparent !important; }
+.bubble .sdot.claude::after {
+  content: "✻"; font-size: 12px; font-weight: 700; line-height: 14px;
+  display: block; text-align: center;
+}
+.bubble .brow[data-state="working"] .sdot.claude::after,
+.bubble .brow[data-state="registered"] .sdot.claude::after { color: var(--amber); }
+.bubble .brow[data-state="waiting"] .sdot.claude::after { color: var(--orange); }
+.bubble .brow[data-state="done"] .sdot.claude::after { color: var(--green); }
+.bubble .sdot.claude.spin::after { animation: claudespin 1.2s linear infinite; transform-origin: center; }
+@keyframes claudespin {
+  from { transform: rotate(0deg); }
+  to { transform: rotate(360deg); }
+}
+
+.bubble .car-dots { display: flex; justify-content: center; gap: 4px; margin-top: 3px; }
+.bubble .car-dot {
+  width: 4px; height: 4px; border-radius: 50%;
+  background: var(--bubble-fg, #F6F0E4); opacity: 0.25; cursor: pointer;
+}
+.bubble .car-dot.sel { opacity: 0.75; }
+
+.bubble .cmp-head { font-size: 0.85em; font-weight: 600; opacity: 0.45; }
+.bubble .cmp-rows { display: flex; flex-direction: column; gap: 3px; }
+.bubble .cmp-fold {
+  background: none; border: 0; padding: 0; cursor: pointer;
+  font: inherit; font-size: 0.85em; font-weight: 500;
+  color: var(--bubble-fg, #F6F0E4); opacity: 0.5; text-align: left;
+}
+.bubble .cmp-fold:hover { opacity: 0.8; }
+
+.bubble .icon-slot { display: inline-flex; align-items: center; flex: 0 0 auto; }
+.bubble .icon-slot.emoji { font-size: 12px; line-height: 14px; }
+.bubble .icon-slot .aicon { width: 14px; height: 14px; }
+
+/* extra-pet right-click context menu */
+.ctx-menu {
+  position: fixed;
+  z-index: 9999;
+  min-width: 160px;
+  padding: 6px;
+  border-radius: 13px;
+  background: rgba(26, 20, 13, 0.97);
+  color: var(--txt);
+  border: 1px solid rgba(232, 176, 106, 0.18);
+  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255,255,255,0.05);
+  font-family: var(--font-ui);
+  font-size: 12px;
+  user-select: none;
+}
+.ctx-menu .ctx-item {
+  display: block;
+  width: 100%;
+  text-align: left;
+  padding: 7px 11px;
+  border: none;
+  border-radius: 8px;
+  background: transparent;
+  color: inherit;
+  font: inherit;
+  cursor: pointer;
+  white-space: nowrap;
+}
+.ctx-menu .ctx-item:hover { background: rgba(255, 255, 255, 0.08); }
+.ctx-menu .ctx-item.sel { color: var(--amber); font-weight: 600; }
+.ctx-menu .ctx-close { color: var(--red); }
+.ctx-menu .ctx-sep {
+  height: 1px;
+  margin: 5px 4px;
+  background: rgba(255, 255, 255, 0.09);
+}
+.ctx-menu .ctx-label {
+  padding: 4px 11px 2px;
+  font-size: 10px;
+  text-transform: uppercase;
+  letter-spacing: 0.5px;
+  opacity: 0.5;
+}
+
+/* ============================================================================
+   3. FLOATING BALL (draggable orb + left-click bubble menu)
+   窗口尺寸硬编码在 floating-ball.ts (WIN_SIZE / MENU_H=420), 布局只改视觉。
+============================================================================ */
+body.floating-ball-body { overflow: hidden; }
+
+.floating-ball-body {
+  --ball-size: 56px;
+  --ball-margin: 12px;
+  --menu-width: 300px;
+  --menu-bg: rgba(24, 18, 12, 0.97);
+  --menu-border: rgba(232, 176, 106, 0.16);
+  font-family: var(--font-ui);
+}
+
+.floating-ball-body #ball {
+  position: absolute;
+  top: var(--ball-margin);
+  left: var(--ball-margin);
+  width: var(--ball-size);
+  height: var(--ball-size);
+  aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  cursor: grab;
+  user-select: none;
+  -webkit-user-select: none;
+
+  /* ember glass orb */
+  background:
+    radial-gradient(circle at 36% 26%, rgba(255, 236, 205, 0.55) 0%, rgba(255, 222, 178, 0.18) 34%, transparent 46%),
+    radial-gradient(circle at 62% 78%, rgba(0, 0, 0, 0.42) 0%, transparent 52%),
+    linear-gradient(160deg, #8A6236 0%, #4A3218 45%, #241708 100%);
+  border: 1.5px solid rgba(255, 222, 178, 0.40);
+  box-shadow:
+    0 3px 8px rgba(0, 0, 0, 0.5),
+    0 0 10px rgba(232, 176, 106, 0.25),
+    inset 0 2px 3px rgba(255, 236, 205, 0.35),
+    inset 0 -3px 6px rgba(0, 0, 0, 0.45),
+    0 0 0 1px rgba(0, 0, 0, 0.15);
+  transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
+              box-shadow 0.18s ease;
+}
+.floating-ball-body #ball:hover {
+  transform: scale(1.05);
+  box-shadow:
+    0 3px 10px rgba(0, 0, 0, 0.5),
+    0 0 12px rgba(232, 176, 106, 0.38),
+    inset 0 2px 3px rgba(255, 236, 205, 0.42),
+    inset 0 -3px 6px rgba(0, 0, 0, 0.45),
+    0 0 0 1px rgba(0, 0, 0, 0.15);
+}
+.floating-ball-body #ball.pressed { transform: scale(0.96); }
+.floating-ball-body #ball.dragging,
+.floating-ball-body #ball.dragging:hover {
+  transform: none;
+  filter: none;
+  transition: none;
+  box-shadow: none;
+  cursor: grabbing;
+}
+.floating-ball-body #ball canvas {
+  width: 62%;
+  height: 62%;
+  aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  image-rendering: pixelated;
+  pointer-events: none;
+  -webkit-user-drag: none;
+}
+
+/* ---- bubble menu --------------------------------------------------------- */
+.floating-ball-body .ball-menu {
+  position: absolute;
+  top: calc(var(--ball-size) + var(--ball-margin) + var(--ball-margin));
+  left: var(--ball-margin);
+  width: var(--menu-width);
+  padding: 15px;
+  border-radius: 18px;
+  background:
+    radial-gradient(300px 160px at 90% -10%, rgba(232, 176, 106, 0.07), transparent 60%),
+    var(--menu-bg);
+  border: 1px solid var(--menu-border);
+  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255,255,255,0.05);
+  color: var(--txt);
+  font-family: var(--font-ui);
+  font-size: 13px;
+  user-select: none;
+  z-index: 10;
+}
+.floating-ball-body .ball-menu .bm-head {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  margin-bottom: 10px;
+}
+.floating-ball-body .ball-menu .bm-title {
+  font-size: 12.5px;
+  font-weight: 650;
+  color: var(--amber);
+  letter-spacing: 0.02em;
+}
+.floating-ball-body .ball-menu .bm-hint {
+  font-size: 10px;
+  color: rgba(216, 202, 178, 0.45);
+}
+.floating-ball-body .ball-menu .bm-target {
+  display: flex;
+  gap: 3px;
+  margin-bottom: 11px;
+  background: rgba(0, 0, 0, 0.28);
+  border: 1px solid rgba(255,255,255,0.05);
+  border-radius: 10px;
+  padding: 3px;
 }
