    filePick.click();
  };
  createBtn.onclick = () => {
    const pet = { slug: `local-${Date.now()}`, name: name.value.trim(), url: dataUrl, custom: true };
    addToLibrary(pet);
    addInstanceFromLibrary(pet);
    modal.hidden = true;
  };
}

