1121	function initSounds() {
1122	  const filePick = document.createElement("input");
1123	  filePick.type = "file";
1124	  filePick.accept = "audio/*";
1125	  filePick.style.display = "none";
1126	  document.body.appendChild(filePick);
1127	
1128	  const syncNames = () => {
1129	    for (const ev of ["done", "waiting"] as const) {
1130	      const name = localStorage.getItem(`ap_sound_${ev}_name`);
1131	      (document.getElementById(`sound-${ev}-name`) as HTMLElement).textContent = name || t("Default");
1132	      (document.getElementById(`t-df-${ev}`) as HTMLElement).style.display = name ? "" : "none";
1133	    }
1134	  };
1135	  syncNames();
1136	
1137	  document.querySelectorAll<HTMLButtonElement>(".sound-btns .mini").forEach((b) => {
1138	    const ev = b.dataset.ev as "done" | "waiting";
1139	    b.onclick = () => {
1140	      switch (b.dataset.act) {
1141	        case "play": playSound(ev); break;
1142	        case "reset":
1143	          localStorage.removeItem(`ap_sound_${ev}_data`);
1144	          localStorage.removeItem(`ap_sound_${ev}_name`);
1145	          syncNames();
1146	          break;
1147	        case "upload":
1148	          filePick.onchange = () => {
1149	            const f = filePick.files?.[0];
1150	            if (!f) return;
1151	            if (f.size > 2_000_000) { alert(t("Sound file too large (max 2 MB)")); return; }
1152	            const reader = new FileReader();
1153	            reader.onload = () => {
1154	              localStorage.setItem(`ap_sound_${ev}_data`, String(reader.result));
1155	              localStorage.setItem(`ap_sound_${ev}_name`, f.name);
1156	              syncNames();
1157	              playSound(ev); // preview, like macOS
1158	            };
1159	            reader.readAsDataURL(f);
1160	            filePick.value = "";
1161	          };
1162	          filePick.click();
1163	          break;
1164	      }
1165	    };
1166	  });
1167	}
