 29	
 30	export function initRoam(pet: Pet, configSource?: ConfigSource): void {
 31	  setRoamConfigSource(configSource ?? null);
 32	  initEngine(pet);
 33	}
 34	
 35	export function destroyRoam(): void {
 36	  setRoamConfigSource(null);
 37	  destroyEngine();
 38	}
