 40	export function isRoamingEnabled(): boolean {
 41	  return localStorage.getItem(ROAM_KEY) !== "0";
 42	}
 43	
 44	export function setRoamEnabled(enabled: boolean): void {
 45	  localStorage.setItem(ROAM_KEY, enabled ? "1" : "0");
 46	}
 47	
 48	export function getRoamMode(): RoamMode {
 49	  return loadConfig().mode;
 50	}
 51	
 52	export function setRoamMode(mode: RoamMode): void {
 53	  if (VALID_MODES.includes(mode)) {
 54	    localStorage.setItem(ROAM_MODE_KEY, mode);
 55	  }
 56	}
 57	
 58	export function getRoamSpeed(): number {
 59	  return loadConfig().speed;
 60	}
