 63	  localStorage.setItem(ROAM_SPEED_KEY, String(Math.max(1, Math.min(10, speed))));
 64	}
 65	// Movement engine: owns the tick loop, coordinates drag sampling, throw/fall
 66	// physics, and dispatches to the active movement mode.
 67	
 68	import { invoke } from "@tauri-apps/api/core";
 69	import { getCurrentWindow } from "@tauri-apps/api/window";
 70	import type { Pet } from "../pet";
 71	import { fetchEnvironment } from "./environment";
 72	import { runMode } from "./modes";
 73	import {
 74	  applyFall,
 75	  applyThrow,
 76	  cancelThrow,
 77	  clearSamples,
 78	  isThrowing,
 79	  recordSample,
 80	  releaseVelocity,
 81	} from "./physics";
 82	import type { Config, Environment, Point, RoamMode } from "./types";
 83	import {
 84	  SLEEP_AFTER_MS,
 85	  SLEEP_ROW_DEFAULT,
 86	  THROW_MIN_SPEED,
 87	  TICK_MS,
 88	  clampToBounds,
 89	  loadConfig,
 90	  sleep,
 91	} from "./types";
 92	import { currentLogicalPos, setDragPositionTracking, setLogical, setPhysical } from "./window";
 93	
 94	/// Tick delay when the pet is resting / sleeping / stationary. The active
 95	/// TICK_MS (30ms) is only needed while the pet is actually moving — resting
 96	/// states (restUntil, sleep, stay mode) only need to check periodically whether
 97	/// to wake up. 200ms cuts IPC calls from 33/sec to 5/sec while idle, with no
 98	/// visible change (the pet resumes walking within one idle-tick of restUntil
 99	/// expiring, imperceptible for a desktop companion).
100	const IDLE_TICK_MS = 200;
101	
102	let petRef: Pet | null = null;
103	let dragging = false;
104	let releasePending = false;
105	let stopRequested = false;
106	
107	/// Mood drives two behaviors: pause roaming while the user needs to read the
108	/// bubble (waiting / celebrate), and let the pet doze off when idle.
109	let mood: string = "idle";
110	let lastMoveTs = Date.now();
111	let sleeping = false;
112	
113	/// Moods that freeze the pet so the bubble / celebration animation stays readable.
114	const MOOD_PAUSES_ROAM = new Set(["waiting", "celebrate"]);
115	
116	function stop(): boolean { return stopRequested; }
117	
118	/// Called from main.ts after each mood evaluation. Non-idle moods wake the pet.
119	export function setMood(m: string): void {
120	  mood = m;
121	  if (m !== "idle") wake();
122	}
123	
124	function wake(): void {
125	  if (!sleeping) return;
126	  sleeping = false;
127	  petRef?.clearRow();
128	}
129	
130	function enterSleep(): void {
131	  if (sleeping) return;
132	  sleeping = true;
133	  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
134	  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
135	  petRef?.setRow(row);
136	}
137	
138	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
139	/// Returns true when the pet is actively moving/interacting and needs the fast
140	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
141	/// idle (200ms) tick and skip most IPC calls.
142	async function tick(): Promise<boolean> {
143	  if (isThrowing()) return true;
144	  if (dragging) {
145	    const pos = await currentLogicalPos();
146	    if (pos) recordSample(pos);
147	    return true;
148	  }
149	  if (releasePending) {
150	    releasePending = false;
151	    const vel = releaseVelocity();
152	    clearSamples();
153	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
154	      wake();
155	      await handleDragRelease(vel);
156	      return true;
157	    }
158	  }
159	
160	  // Mood-driven freeze: keep the pet still while the user needs to see the
161	  // bubble or the celebrate burst. Throws and drags above still work.
162	  if (MOOD_PAUSES_ROAM.has(mood)) {
163	    wake();
164	    petRef?.clearRow();
165	    return false;
166	  }
167	
168	  const cfg = loadConfig();
169	  if (!cfg.enabled || cfg.mode === "stay") {
170	    handleStationary();
171	    return false;
172	  }
173	
174	  wake();
175	  const moved = await stepMode(cfg.mode);
176	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
177	    enterSleep();
178	  }
179	  return moved;
180	}
181	
182	/// Run one mode step and apply it. Returns true if the pet actually moved.
183	async function stepMode(mode: RoamMode): Promise<boolean> {
184	  const env = await fetchEnvironment(mode === "climb");
185	  if (!env) return false;
186	  const pos = await currentLogicalPos();
187	  if (!pos) return false;
188	
189	  const next = await runMode(mode, { env, pos, pet: petRef });
190	  const clamped = clampToBounds(next, env.workArea);
191	  const moved = Math.abs(clamped.x - pos.x) >= 0.5 || Math.abs(clamped.y - pos.y) >= 0.5;
192	  if (!moved) {
193	    return false;
194	  }
195	  lastMoveTs = Date.now();
196	  try { await setLogical(clamped); }
197	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
198	  return true;
199	}
200	
201	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
202	function handleStationary(): void {
203	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
204	    enterSleep();
205	  } else {
206	    wake();
207	    petRef?.clearRow();
208	  }
209	}
210	
211	type ReleaseContext = {
212	  config: Config;
213	  environment: Environment;
214	};
215	
216	type ConfigReader = () => Config;
217	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
218	
219	export async function resolveReleaseContext(
220	  getConfig: ConfigReader = loadConfig,
221	  getEnvironment: EnvironmentReader = fetchEnvironment,
222	): Promise<ReleaseContext | null> {
223	  let config = getConfig();
224	  const includedSystemWindows = config.mode === "climb";
225	  let environment = await getEnvironment(includedSystemWindows);
226	  if (!environment) return null;
227	
228	  config = getConfig();
229	  if (config.mode === "climb" && !includedSystemWindows) {
230	    environment = await getEnvironment(true);
231	    if (!environment) return null;
232	  }
233	
234	  return { config: getConfig(), environment };
235	}
236	
237	async function persistPetPosition(): Promise<void> {
238	  try {
239	    await invoke<void>("persist_pet_position", { label: getCurrentWindow().label });
240	  } catch (error) {
241	    console.error("Unable to persist pet position", error);
242	  }
243	}
244	
245	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
246	  const context = await resolveReleaseContext();
247	  if (!context) return;
248	  const { config: cfg, environment: env } = context;
249	
250	  if (cfg.mode === "climb" && env.windows.length > 0) {
251	    const surfaces = env.windows.map((w) => w.rect);
252	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
253	  } else {
254	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
255	  }
256	  await persistPetPosition();
257	}
258	
259	async function loop(): Promise<void> {
260	  while (!stopRequested) {
261	    const active = await tick();
262	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
263	  }
264	  petRef?.clearRow();
265	}
266	
267	export function initEngine(pet: Pet): void {
268	  if (petRef) return;
269	  petRef = pet;
270	  stopRequested = false;
271	  lastMoveTs = Date.now();
272	  mood = "idle";
273	  sleeping = false;
274	  void loop();
275	}
276	
277	export function destroyEngine(): void {
278	  stopRequested = true;
279	  cancelThrow();
280	  petRef = null;
281	}
282	
283	export function setDragging(isDragging: boolean): void {
284	  dragging = isDragging;
285	  setDragPositionTracking(isDragging);
286	  if (isDragging) {
287	    cancelThrow();
288	    clearSamples();
289	    wake();
290	    releasePending = false;
291	  } else if (petRef) {
292	    releasePending = true;
293	  }
294	}
295	
296	/// Starts a pointer-managed drag after its native interaction lease is active.
297	/// The starting position is sampled explicitly so a quick drag need not wait
298	/// for two engine ticks before it can produce a throw velocity.
299	export async function beginManualDrag(): Promise<void> {
300	  setDragging(true);
301	  const position = await currentLogicalPos();
302	  if (position && dragging) recordSample(position);
303	}
304	
305	/// Moves the window in physical coordinates and records every successful
306	/// manual position in the same logical coordinate system used by physics.
307	export async function moveManualDrag(position: Point): Promise<void> {
308	  const logicalPosition = await setPhysical(position);
309	  if (dragging) recordSample(logicalPosition);
310	}
311	
312	export function finishManualDrag(): void {
313	  setDragging(false);
314	}
315	// Shared window-position helpers. Both the engine (tick loop) and the physics
316	// module (throw/fall) need to read and write the pet window's logical position;
317	// centralizing it keeps the DPI conversion in one place and avoids two copies
318	// of the same `outerPosition / scaleFactor` dance drifting apart.
319	
320	import { getCurrentWindow } from "@tauri-apps/api/window";
321	import { LogicalPosition, PhysicalPosition } from "@tauri-apps/api/dpi";
322	import type { Point } from "./types";
323	
324	const win = getCurrentWindow();
325	
326	let cachedLogicalPos: Point | null = null;
327	let cacheGeneration = 0;
328	let pendingPositionRead: Promise<Point | null> | null = null;
329	let pendingNativeDragMove: Promise<void> | null = null;
330	let nativeDragActive = false;
331	let trackingStarted = false;
332	let pendingTracking: Promise<void> | null = null;
333	
334	function copyPoint(pos: Point): Point {
335	  return { x: pos.x, y: pos.y };
336	}
337	
338	function invalidatePosition(): number {
339	  cacheGeneration += 1;
340	  cachedLogicalPos = null;
341	  return cacheGeneration;
342	}
343	
344	function refreshNativeDragPosition(physical: Point): void {
345	  const generationAtMove = invalidatePosition();
346	  let update: Promise<void>;
347	  update = win.scaleFactor()
348	    .then((scaleFactor) => {
349	      if (!nativeDragActive || generationAtMove !== cacheGeneration) return;
350	      cachedLogicalPos = {
351	        x: physical.x / scaleFactor,
352	        y: physical.y / scaleFactor,
353	      };
354	    })
355	    .catch(() => {
356	      // Keep the cache invalid; the regular reader retries when it is needed.
357	    })
358	    .finally(() => {
359	      if (pendingNativeDragMove === update) pendingNativeDragMove = null;
360	    });
361	  pendingNativeDragMove = update;
362	}
363	
364	function startPositionTracking(): void {
365	  if (trackingStarted || pendingTracking) return;
366	  const movedRegistration = Promise.resolve().then(() =>
367	    win.onMoved(({ payload }) => {
368	      if (nativeDragActive) refreshNativeDragPosition(payload);
369	    }),
370	  );
371	  const scaleRegistration = Promise.resolve().then(() =>
372	    win.onScaleChanged(() => {
373	      invalidatePosition();
374	    }),
375	  );
376	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
377	    .then(([moved, scale]) => {
378	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
379	        trackingStarted = true;
380	        return;
381	      }
382	      if (moved.status === "fulfilled") moved.value();
383	      if (scale.status === "fulfilled") scale.value();
384	    })
385	    .finally(() => {
386	      pendingTracking = null;
387	    });
388	}
389	
390	export function setDragPositionTracking(active: boolean): void {
391	  if (nativeDragActive === active) return;
392	  nativeDragActive = active;
393	  invalidatePosition();
394	}
395	
396	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
397	/// window or scaleFactor can't be read (e.g. window closing).
398	export async function currentLogicalPos(): Promise<Point | null> {
399	  startPositionTracking();
400	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
401	  while (pendingNativeDragMove) {
402	    const update = pendingNativeDragMove;
403	    await update;
404	    if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
405	    if (pendingNativeDragMove === update) break;
406	  }
407	  if (!pendingPositionRead) {
408	    const generationAtReadStart = cacheGeneration;
409	    pendingPositionRead = (async () => {
410	      try {
411	        const sf = await win.scaleFactor();
412	        const p = await win.outerPosition();
413	        if (generationAtReadStart !== cacheGeneration) {
414	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
415	        }
416	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
417	        return copyPoint(cachedLogicalPos);
418	      } catch {
419	        return null;
420	      } finally {
421	        pendingPositionRead = null;
422	      }
423	    })();
424	  }
425	  const pos = await pendingPositionRead;
426	  return pos ? copyPoint(pos) : null;
427	}
428	
429	/// Move the window to a physical-pixel position and return its corresponding
430	/// logical position for roam sampling.
431	export async function setPhysical(pos: Point): Promise<Point> {
432	  const generationAtSetStart = invalidatePosition();
433	  await win.setPosition(new PhysicalPosition(pos.x, pos.y));
434	  const scaleFactor = await win.scaleFactor();
435	  const logical = { x: pos.x / scaleFactor, y: pos.y / scaleFactor };
436	  if (generationAtSetStart === cacheGeneration) cachedLogicalPos = copyPoint(logical);
437	  return logical;
438	}
439	
440	/// Move the window to a logical-pixel position. Caller is responsible for
441	/// clamping to the work area first.
442	export async function setLogical(pos: Point): Promise<void> {
443	  const generationAtSetStart = invalidatePosition();
444	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
445	  if (generationAtSetStart === cacheGeneration && !nativeDragActive) {
446	    cachedLogicalPos = copyPoint(pos);
447	  }
448	}

