  1	import { listen, emit } from "@tauri-apps/api/event";
  2	import "./styles.css";
  3	
  4	import { invoke } from "@tauri-apps/api/core";
  5	import { cursorPosition, getCurrentWindow } from "@tauri-apps/api/window";
  6	import { Pet } from "./pet";
  7	import { ActivityStore, type ActivityEventPayload } from "./state";
  8	import { BubbleRenderer, invalidateBubbleConfig } from "./bubble";
  9	import { libraryUrlForSlug } from "./catalog";
 10	import { t, setLang, type Lang } from "./i18n";
 11	import { bubbleLines, PET_CHAT } from "./activity";
 12	import * as care from "./care";
 13	import { loadPetStore, petInstanceById, type PetInstance } from "./pets";
 14	import { QuickBubbleController, readQuickBubbleDurationMs } from "./quick-bubble";
 15	import { attachPetPointerDrag } from "./pet-pointer-drag";
 16	import {
 17	  beginManualDrag,
 18	  finishManualDrag,
 19	  initRoam,
 20	  moveManualDrag,
 21	  setMood,
 22	} from "./roam";
 23	import { DEFAULT_WANDER_PAUSE_MAX_MS, DEFAULT_WANDER_PAUSE_MIN_MS } from "./roam/pause";
 24	import { WindowDragController } from "./window-drag";
 25	
 26	const MY_INSTANCE_ID = new URLSearchParams(location.search).get("pet");
 27	const MY_LABEL = getCurrentWindow().label;
 28	
 29	function readPetInstance(): PetInstance | null {
 30	  if (!MY_INSTANCE_ID) return null;
 31	  const store = loadPetStore();
 32	  return store ? petInstanceById(store, MY_INSTANCE_ID) : null;
 33	}
 34	
 35	let cachedInstance = readPetInstance();
 36	
 37	function myPetInstance(): PetInstance | null {
 38	  return cachedInstance;
 39	}
 40	
 41	function refreshPetInstance(): void {
 42	  cachedInstance = readPetInstance();
 43	}
 44	
 45	const canvas = document.getElementById("pet") as HTMLCanvasElement;
 46	const bubbleEl = document.getElementById("bubble") as HTMLDivElement;
 47	const pet = new Pet(canvas);
 48	const store = new ActivityStore();
 49	const bubble = new BubbleRenderer(bubbleEl);
 50	initRoam(pet, () => {
 51	  const instance = myPetInstance();
 52	  return instance
 53	    ? {
 54	      enabled: instance.roamEnabled,
 55	      mode: instance.roamMode,
 56	      speed: instance.roamSpeed,
 57	      wanderPauseMinMs: instance.wanderPauseMinMs,
 58	      wanderPauseMaxMs: instance.wanderPauseMaxMs,
 59	    }
 60	    : {
 61	      enabled: false,
 62	      mode: "stay",
 63	      speed: 1,
 64	      wanderPauseMinMs: DEFAULT_WANDER_PAUSE_MIN_MS,
 65	      wanderPauseMaxMs: DEFAULT_WANDER_PAUSE_MAX_MS,
 66	    };
 67	});
 68	
 69	// --- bubble appearance (theme / opacity / fonts) ------------------------------
 70	const FONT_FAMILIES: Record<string, string> = {
 71	  system: '"Segoe UI", system-ui, sans-serif',
 72	  rounded: '"Segoe UI Rounded", "Nunito", "Segoe UI", sans-serif',
 73	  mono: 'Consolas, "Courier New", monospace',
 74	};
 75	
 76	function applyBubble() {
 77	  let theme = localStorage.getItem("ap_theme") || "dark";
 78	  if (theme === "system") theme = matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
 79	  const op = (parseInt(localStorage.getItem("ap_opacity") || "92", 10) || 92) / 100;
 80	  const r = document.documentElement.style;
 81	  if (theme === "light") {
 82	    r.setProperty("--bubble-bg", `rgba(255,255,255,${op})`);
 83	    r.setProperty("--bubble-fg", "#3A2C1A");
 84	    r.setProperty("--bubble-border", "rgba(0,0,0,0.08)");
 85	  } else {
 86	    r.setProperty("--bubble-bg", `rgba(26,20,13,${op})`);
 87	    r.setProperty("--bubble-fg", "#ffffff");
 88	    r.setProperty("--bubble-border", "rgba(255,255,255,0.10)");
 89	  }
 90	  r.setProperty("--bubble-font-size", `${parseInt(localStorage.getItem("ap_font_size") || "12", 10) || 12}px`);
 91	  r.setProperty("--bubble-font-family", FONT_FAMILIES[localStorage.getItem("ap_font_family") || "system"] ?? FONT_FAMILIES.system);
 92	}
 93	applyBubble();
 94	
 95	// Pet size + idle bob FX. Size belongs to the displayed instance, so two
 96	// instances using the same spritesheet remain independently configurable.
 97	function applyPet() {
 98	  const size = (myPetInstance()?.size ?? 100) / 100;
 99	  canvas.style.width = `${Math.round(160 * size)}px`;
100	  canvas.style.height = `${Math.round(180 * size)}px`;
101	  canvas.classList.toggle("bob", localStorage.getItem("ap_fx") === "1");
102	}
103	applyPet();
104	
105	// Simple synthesized chimes (no audio assets needed). Per-event enable, like
106	// the macOS SoundSettings (done = high glass-ish, waiting = lower submarine).
107	let audioCtx: AudioContext | null = null;
108	function chime(event: "done" | "waiting") {
109	  const key = event === "done" ? "ap_sound_done" : "ap_sound_waiting";
110	  const legacy = localStorage.getItem("ap_sound"); // pre-split toggle
111	  const enabled = localStorage.getItem(key) ?? (legacy === "0" ? "0" : "1");
112	  if (enabled === "0") return;
113	  // Custom uploaded sound wins (mac SoundSettings custom file).
114	  const data = localStorage.getItem(`ap_sound_${event}_data`);
115	  if (data) {
116	    try { void new Audio(data).play(); return; } catch {}
117	  }
118	  try {
119	    audioCtx = audioCtx || new AudioContext();
120	    const o = audioCtx.createOscillator();
121	    const g = audioCtx.createGain();
122	    o.type = "sine";
123	    o.frequency.value = event === "done" ? 880 : 560;
124	    g.gain.value = 0.05;
125	    o.connect(g);
126	    g.connect(audioCtx.destination);
127	    o.start();
128	    o.stop(audioCtx.currentTime + 0.13);
129	  } catch {}
130	}
131	
132	// --- pick + load this instance's pet sprite -----------------------------------
133	function loadInstanceSprite() {
134	  const instance = myPetInstance();
135	  if (!instance) return;
136	  const url = libraryUrlForSlug(instance.spriteSlug)
137	    ?? (instance.id === "legacy-pet" ? localStorage.getItem("ap_pet_custom") || localStorage.getItem("ap_pet_url") : null);
138	  if (url) pet.load(url);
139	}
140	loadInstanceSprite();
141	
142	// --- mood + render loop --------------------------------------------------------
143	// Port of PetController: aggregate mood from the activity store, a 3s
144	// celebrate burst when entering done, a persistent idle line (re-picked on
145	// mood transitions, not blinking). Phase 1 has no activity producers yet, so
146	// the pet idles unless a celebrate/level-up flash is triggered (care feeds).
147	let celebrateUntil = 0;
148	let wasCelebrating = false;
149	let moodLine = ""; // the single-bubble line for idle/done/celebrate
150	let celebrateText = "";
151	
152	// Quick bubbles override the normal mood bubble until their own timer expires.
153	// The rendering signature must be invalidated at expiry so a previously cached
154	// idle state cannot leave the quick text visible indefinitely.
155	const QUICK_KEY = "ap_quick_bubbles";
156	let renderSig = "";
157	const quickBubble = new QuickBubbleController({
158	  now: () => Date.now(),
159	  schedule: (callback, delay) => window.setTimeout(callback, delay),
160	  cancel: (timer) => window.clearTimeout(timer as number),
161	}, () => {
162	  renderSig = "";
163	  render();
164	});
165	
166	function readQuickPresets(): string[] {
167	  try {
168	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
169	    return Array.isArray(v) ? v.filter((x: unknown) => typeof x === "string" && x.trim()) : [];
170	  } catch { return []; }
171	}
172	function randomPreset(): string | null {
173	  const list = readQuickPresets();
174	  if (!list.length) return null;
175	  return list[Math.floor(Math.random() * list.length)];
176	}
177	function showQuickBubble(text: string) {
178	  quickBubble.show(text, readQuickBubbleDurationMs());
179	  render();
180	}
181	/// Play a celebrate burst with a custom line (achievement/level-up), then
182	/// settle back to the aggregate mood (mac PetController.flashCelebrate).
183	function flashCelebrate(line: string) {
184	  celebrateText = line;
185	  celebrateUntil = Date.now() + 3000;
186	  render();
187	}
188	
189	/// Feed this instance through a care mutation; on level-up plays a celebrate
190	/// burst in the same window.
191	export function feedPet(instanceId: string, change: (s: care.CareState) => void) {
192	  const before = care.stateFor(instanceId);
193	  const levelBefore = care.levelForXP(before.xp);
194	  care.mutate(instanceId, change);
195	  const after = care.stateFor(instanceId);
196	  emit("care-updated", { instanceId });
197	  const levelAfter = care.levelForXP(after.xp);
198	  if (levelAfter > levelBefore) {
199	    flashCelebrate(`${t("Level up")}! ${t("Lv")} ${care.displayLevel(after.xp)}`);
200	    chime("done");
201	  }
202	}
203	
204	function pickMoodLine(mood: string) {
205	  // Custom/system pools; working/waiting fall back to the PetChat lines so the
206	  // simple bubble always has something to say.
207	  let pool = bubbleLines(null, mood);
208	  if (!pool.length) pool = PET_CHAT[mood] ?? [];
209	  moodLine = pool.length ? pool[Math.floor(Math.random() * pool.length)] : "";
210	}
211	
212	// Render signature: when nothing changed, skip the DOM writes and IPC calls
213	// entirely. The 500ms timer keeps ticking but becomes a no-op while the pet is
214	// idle, instead of doing a full pass every tick.
215	
216	function render() {
217	  const now = Date.now();
218	  // Quick bubble overrides everything for its configured duration after the
219	  // user sends a message from the floating ball or clicks the pet.
220	  const quickBubbleText = quickBubble.current();
221	  if (quickBubbleText !== null) {
222	    bubble.renderLine(quickBubbleText);
223	    snugBubble();
224	    reportHitRect();
225	    return;
226	  }
227	  const resolved = store.topState() === "done" ? "done" : "idle";
228	  const celebrating = now < celebrateUntil;
229	  const mood = celebrating ? "celebrate" : resolved;
230	  pet.setState(mood);
231	  setMood(mood);
232	  if (celebrating && wasCelebrating && now >= celebrateUntil) {
233	    // burst ended, settle into the actual mood's line
234	    pickMoodLine(resolved === "idle" ? "idle" : "done");
235	  }
236	  wasCelebrating = celebrating;
237	
238	  const sig = [mood, moodLine, celebrating ? celebrateText : ""].join("|");
239	  if (sig !== renderSig) {
240	    renderSig = sig;
241	    if (celebrating) {
242	      bubble.renderLine(celebrateText || t("Done"));
243	    } else if (resolved === "done") {
244	      if (!moodLine) pickMoodLine("done");
245	      bubble.renderLine(moodLine);
246	    } else if (localStorage.getItem("ap_idle") !== "0") {
247	      if (!moodLine) pickMoodLine("idle");
248	      bubble.renderLine(moodLine);
249	    } else {
250	      bubble.hide();
251	    }
252	  }
253	
254	  snugBubble();
255	  reportHitRect();
256	}
257	
258	setInterval(render, 500);
259	// Hunger decays over time, so re-render so the idle line (hunger-aware) can
260	// refresh on the care timer, matching macOS's state-republish trigger.

