408	  // make moveToward stop without advanceWander picking a new target, and the
409	  // pet would stand still forever.
410	  if (dist < ARRIVAL_DISTANCE) {
411	    wanderTarget = null;
412	    restUntil = Date.now() + sampleWanderPauseMs(pauseRange);
413	    pet?.clearRow();
414	    return pos;
415	  }
416	  return moveToward(target, pos, env.workArea, pet);
417	}
418	
419	/// Climb along the top edges of visible application windows, like Shimeji.
420	/// Moves to the nearest reachable window top before walking its edge, then
421	/// pauses and reverses direction at an edge.
422	async function climb(ctx: ModeContext): Promise<Point> {
423	  const { env, pos, pet } = ctx;
424	  if (env.windows.length === 0) {
425	    climbDirection = null;
426	    return fallbackWander(ctx);
427	  }
428	  if (Date.now() < restUntil) {
429	    return pos;
430	  }
431	
432	  const surface = findSurfaceBelow(pos, env);
433	  if (!surface.isWindow || !isStandingOnSurface(pos, surface, env.workArea)) {
434	    climbDirection = null;
435	    const target = nearestClimbTarget(pos, env);
436	    return target ? moveToward(target, pos, env.workArea, pet) : fallbackWander(ctx);
437	  }
438	
439	  const support = surfaceSupportRange(surface.rect, env.workArea);
440	  if (!support) {
441	    climbDirection = null;
442	    return fallbackWander(ctx);
443	  }
444	  const standY = climbTopY(surface.rect, env.workArea);
445	
446	  const dir = climbDirection ?? (Math.random() < 0.5 ? -1 : 1);
447	  climbDirection = dir;
448	  const step = pxPerSec(loadConfig().speed) * DT_SEC;
449	  const nextX = pos.x + dir * step;
450	  const onEdge = nextX < support.left - 2 || nextX > support.right + 2;
451	
452	  if (onEdge) {
453	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
454	    climbDirection = dir === 1 ? -1 : 1;
455	    pet?.clearRow();
456	    return {
457	      x: Math.max(support.left, Math.min(support.right, pos.x)),
458	      y: standY,
459	    };
460	  }
461	
462	  const next = clampToBounds(
463	    { x: nextX, y: standY },
464	    env.workArea,
465	  );
466	  pet?.setRow(dir > 0 ? ROW_RIGHT : ROW_LEFT);
467	  return next;
468	}
469	
470	function moveToward(target: Point, pos: Point, bounds: Rect, pet: Pet | null): Point {
471	  const dx = target.x - pos.x;
472	  const dy = target.y - pos.y;
473	  const dist = Math.hypot(dx, dy);
474	  if (dist < ARRIVAL_DISTANCE) { pet?.clearRow(); return pos; }
475	  const speed = pxPerSec(loadConfig().speed);
476	  const move = Math.min(dist, speed * DT_SEC);
477	  const next = clampToBounds(
478	    { x: pos.x + (dx / dist) * move, y: pos.y + (dy / dist) * move },
479	    bounds,
480	  );
481	  pet?.setRow(dx > 0 ? ROW_RIGHT : ROW_LEFT);
482	  return next;
483	}
484	
485	function randomTarget(bounds: Rect): Point {
486	  const x = bounds.left + MARGIN + Math.random() * Math.max(1, bounds.right - bounds.left - WIN_W - MARGIN * 2);
487	  const y = bounds.top + MARGIN + Math.random() * Math.max(1, bounds.bottom - bounds.top - WIN_H - MARGIN * 2);
488	  return { x, y };
489	}
490	
491	interface SurfaceInfo { rect: Rect; isWindow: boolean }
492	
493	type SurfaceSupport = { left: number; right: number };
494	
495	function surfaceSupportRange(rect: Rect, bounds: Rect): SurfaceSupport | null {
496	  const left = Math.max(bounds.left, rect.left - WIN_W / 2);
497	  const right = Math.min(bounds.right - WIN_W, rect.right - WIN_W / 2);
498	  return left <= right ? { left, right } : null;
499	}
500	
501	/// Logical y for the pet window's TOP edge when standing on this surface.
502	/// A window whose top edge sits too high for the pet to stand on (standing on
503	/// it would push the pet off the top of the screen) is treated as reachable at
504	/// the screen top: the pet is pinned to the top edge instead of falling back
505	/// to random roaming on maximized/fullscreen desktops.
506	function climbTopY(rect: Rect, workArea: Rect): number {
507	  return Math.max(rect.top - WIN_H, workArea.top);
508	}
509	
510	function isStandingOnSurface(pos: Point, surface: SurfaceInfo, workArea: Rect): boolean {
511	  return Math.abs(pos.y - climbTopY(surface.rect, workArea)) < ARRIVAL_DISTANCE;
512	}
513	
514	function nearestClimbTarget(pos: Point, env: Environment): Point | null {
515	  let nearest: Point | null = null;
516	  let nearestDistance = Infinity;
517	
518	  for (const window of env.windows) {
519	    const support = surfaceSupportRange(window.rect, env.workArea);
520	    // climbTopY clamps to the screen top, so only window tops below the
521	    // reachable band are skipped (they would push the pet off the bottom).
522	    const y = climbTopY(window.rect, env.workArea);
523	    if (!support || y > env.workArea.bottom - WIN_H) continue;
524	
525	    const target = { x: Math.max(support.left, Math.min(support.right, pos.x)), y };
526	    const distance = Math.hypot(target.x - pos.x, target.y - pos.y);
527	    if (distance < nearestDistance) {
528	      nearest = target;
529	      nearestDistance = distance;
530	    }
531	  }
532	
533	  return nearest;
534	}
535	
536	function findSurfaceBelow(pos: Point, env: Environment): SurfaceInfo {
537	  // Standing on a window means the pet's top sits exactly at that window's
538	  // climbTopY (within the arrival margin), matching isStandingOnSurface so
539	  // the two can never disagree.
540	  for (const w of env.windows) {
541	    const support = surfaceSupportRange(w.rect, env.workArea);
542	    if (!support || pos.x < support.left - ARRIVAL_DISTANCE || pos.x > support.right + ARRIVAL_DISTANCE) continue;
543	    if (Math.abs(pos.y - climbTopY(w.rect, env.workArea)) < ARRIVAL_DISTANCE) {
544	      return { rect: w.rect, isWindow: true };
545	    }
546	  }
547	  return { rect: env.workArea, isWindow: false };
548	}
549	// Shared types and constants for the roam subsystem.
550	
551	import { getCurrentWindow } from "@tauri-apps/api/window";
552	import {
553	  DEFAULT_WANDER_PAUSE_MAX_MS,
554	  DEFAULT_WANDER_PAUSE_MIN_MS,
555	  normalizeWanderPauseRange,
556	} from "./pause";
557	
558	export type RoamMode = "stay" | "wander" | "cursor" | "climb";
559	
560	export type Point = { x: number; y: number };
561	
562	export type Rect = {
563	  left: number;
564	  top: number;
565	  right: number;
566	  bottom: number;
567	};
568	
569	export type SystemWindow = {
570	  title: string;
571	  rect: Rect;
572	};
573	
574	export type Environment = {
575	  /// Work area of the current monitor (excludes taskbar), in logical pixels.
576	  workArea: Rect;
577	  /// Other application windows visible on screen, in logical pixels.
578	  /// Empty on platforms where enumeration is unavailable.
579	  windows: SystemWindow[];
580	};
581	
582	export type Config = {
583	  enabled: boolean;
584	  mode: RoamMode;
585	  speed: number;
586	  wanderPauseMinMs: number;
587	  wanderPauseMaxMs: number;
588	};
589	
590	export type ConfigSource = () => Config;
591	
592	export const ROAM_KEY = "ap_roam";
593	export const ROAM_MODE_KEY = "ap_roam_mode";
594	export const ROAM_SPEED_KEY = "ap_roam_speed";
595	
596	export const WIN_W = 260;
597	export const WIN_H = 320;
598	export const MARGIN = 40;
599	
600	export const IDLE_MS_MIN = 1200;

