191	function mulberry32(seed: number) {
192	  let a = seed >>> 0;
193	  return () => {
194	    a |= 0; a = (a + 0x6d2b79f5) | 0;
195	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
196	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
197	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
198	  };
199	}
