203	/// Mirrors engine.stepMode: clamp, then treat <0.5px movement as stationary.
204	async function stepMode(env: Environment, pos: Point): Promise<{ next: Point; moved: boolean }> {
205	  const next = await runMode("climb", { env, pos, pet: pet as never });
206	  const clamped = clampToBounds(next, env.workArea);
207	  const moved = Math.abs(clamped.x - pos.x) >= 0.5 || Math.abs(clamped.y - pos.y) >= 0.5;
208	  return { next: clamped, moved };
209	}
