211	async function simulateEngine(env: Environment, start: Point, ticks = 900): Promise<boolean> {
212	  let pos = start;
213	  let stallRun = 0;
214	  let finalStuck = false;
215	  const t0 = Date.now();
216	  await runMode("wander", { env, pos, pet: pet as never }); // reset module state
217	  const rng = mulberry32(7777);
218	  const spy = vi.spyOn(Math, "random").mockImplementation(rng);
219	  try {
220	    for (let i = 0; i < ticks; i++) {
221	      // real loop sleeps 30ms when moving, 200ms when stationary
222	      vi.setSystemTime(t0 + i * (stallRun > 0 ? 200 : 30));
223	      const { next, moved } = await stepMode(env, pos);
224	      stallRun = moved ? 0 : stallRun + 1;
225	      // stationary for the final ~9s (resting pauses are <= 3.5s) => stuck
226	      if (i > ticks - 300 && stallRun > 60) finalStuck = true;
227	      pos = next;
228	    }
229	  } finally {
230	    spy.mockRestore();
231	  }
232	  return finalStuck;
233	}
