   179	  quickBubble.show(text, readQuickBubbleDurationMs());
   180	  render();
   181	}
   182	/// Play a celebrate burst with a custom line (achievement/level-up), then
   183	/// settle back to the aggregate mood (mac PetController.flashCelebrate).
   184	function flashCelebrate(line: string) {
   185	  celebrateText = line;
   186	  celebrateUntil = Date.now() + 3000;
   187	  render();
   188	}
   189	
   190	/// Feed this instance through a care mutation; on level-up plays a celebrate
   191	/// burst in the same window.
   192	export function feedPet(instanceId: string, change: (s: care.CareState) => void) {
   193	  const before = care.stateFor(instanceId);
   194	  const levelBefore = care.levelForXP(before.xp);
   195	  care.mutate(instanceId, change);
   196	  const after = care.stateFor(instanceId);
   197	  emit("care-updated", { instanceId });
   198	  const levelAfter = care.levelForXP(after.xp);
   199	  if (levelAfter > levelBefore) {
   200	    flashCelebrate(`${t("Level up")}! ${t("Lv")} ${care.displayLevel(after.xp)}`);
   201	    chime("done");
   202	  }
   203	}
   204	
   205	function pickMoodLine(mood: string) {
   206	  // Custom/system pools; working/waiting fall back to the PetChat lines so the
   207	  // simple bubble always has something to say.
   208	  let pool = bubbleLines(null, mood);
   209	  if (!pool.length) pool = PET_CHAT[mood] ?? [];
   210	  moodLine = pool.length ? pool[Math.floor(Math.random() * pool.length)] : "";
   211	}
   212	
   213	// Render signature: when nothing changed, skip the DOM writes and IPC calls
   214	// entirely. The 500ms timer keeps ticking but becomes a no-op while the pet is
   215	// idle, instead of doing a full pass every tick.
   216	
   217	function render() {
   218	  const now = Date.now();
   219	  // Quick bubble overrides everything for its configured duration after the
   220	  // user sends a message from the floating ball or clicks the pet.
   221	  const quickBubbleText = quickBubble.current();
   222	  if (quickBubbleText !== null) {
   223	    quickBubbleWasVisible = true;
   224	    bubble.renderLine(quickBubbleText);
   225	    snugBubble();
   226	    reportHitRect();
   227	    return;
   228	  }
   229	  if (quickBubbleWasVisible) {
   230	    quickBubbleWasVisible = false;
   231	    renderSig = "";
   232	  }
   233	  const resolved = store.topState() === "done" ? "done" : "idle";
   234	  const celebrating = now < celebrateUntil;
   235	  const mood = celebrating ? "celebrate" : resolved;
   236	  pet.setState(mood);
   237	  setMood(mood);
   238	  if (celebrating && wasCelebrating && now >= celebrateUntil) {
   239	    // burst ended, settle into the actual mood's line
   240	    pickMoodLine(resolved === "idle" ? "idle" : "done");
   241	  }
   242	  wasCelebrating = celebrating;
   243	
   244	  const sig = [mood, moodLine, celebrating ? celebrateText : ""].join("|");
   245	  if (sig !== renderSig) {
   246	    renderSig = sig;
   247	    if (celebrating) {
   248	      bubble.renderLine(celebrateText || t("Done"));
   249	    } else if (resolved === "done") {
   250	      if (!moodLine) pickMoodLine("done");
   251	      bubble.renderLine(moodLine);
   252	    } else if (localStorage.getItem("ap_idle") !== "0") {
   253	      if (!moodLine) pickMoodLine("idle");
   254	      bubble.renderLine(moodLine);
   255	    } else {
   256	      bubble.hide();
   257	    }
   258	  }
   259	
   260	  snugBubble();
   261	  reportHitRect();
   262	}
   263	
   264	setInterval(render, 500);
   265	// Hunger decays over time, so re-render so the idle line (hunger-aware) can
   266	// refresh on the care timer, matching macOS's state-republish trigger.
   267	setInterval(() => { moodLine = ""; render(); }, 60_000);
